{% from "hipersign_trading/templates/print/macros.html" import styles, header, items, totals, signs, bank %}
{{ styles() }}
<div class="hs-doc">
{{ header("ORDER CONFIRMATION", "تأكيد أمر البيع", doc.name, doc.transaction_date, doc.company) }}
<div class="hs-two"><div><div class="hs-h4">Customer · العميل</div><b>{{ doc.customer_name }}</b><br>{{ doc.address_display or "" }}{% if doc.contact_display %}<br>Attn: {{ doc.contact_display }}{% if doc.contact_mobile %} · {{ doc.contact_mobile }}{% endif %}{% endif %}{% if doc.tax_id %}<br>TRN {{ doc.tax_id }}{% endif %}</div><div><div class="hs-h4">Order · الطلب</div>Your PO: {{ doc.po_no or "—" }}<br>Delivery date: {{ frappe.utils.formatdate(doc.delivery_date) }}<br>Deliver to: {{ doc.shipping_address_name or doc.customer_address or "—" }}<br>Payment terms: {{ doc.payment_terms_template or "As agreed" }}</div></div>
{{ items(doc) }}
{{ totals(doc) }}
<div class="hs-note">We confirm your order on the terms above. Delivery is subject to stock and site access; changes to quantities or delivery address must be confirmed in writing.</div>
{{ signs("For " ~ doc.company, "Acknowledged by the customer") }}
</div>
